function claimPlayerView(){const claimed=new Set(collabRoom?.claimed_indices||[]),owner=shareAccess?.code===sharedCode;return `<section class="panel collab-card"><p class="eyebrow">${lt('Entra nella partita','Join the game','Oyuna katıl')}</p><h2>${lt('Chi sei?','Who are you?','Kimsiniz?')}</h2><p class="subtle">${lt('Scegli il tuo nome. Questo telefono potrà inserire solo il tuo punteggio.','Choose your name. This phone can enter only your score.','Adınızı seçin. Bu telefon yalnızca sizin puanınızı girebilir.')}</p><div class="claim-list">${state.players.map((name,i)=>claimed.has(i)?`<div class="claimed-player">${avatar(name,i,'small')}<strong>${esc(name)}</strong><span>${lt('Già collegato','Already connected','Zaten bağlı')}</span>${owner?`<button data-release="${i}">${lt('Libera','Release','Serbest bırak')}</button>`:''}</div>`:`<button class="mode-btn" data-claim="${i}">${avatar(name,i,'small')}<strong>${esc(name)}</strong><span>${lt('Usa questo profilo','Use this profile','Bu profili kullan')}</span></button>`).join('')}</div></section>`;}
function collaborativeView(){
 const me=collabSession.playerIndex,current=collabRoom?.current_round||{},entries=collabRoom?.entries||[],mine=entries.find(x=>x.playerIndex===me),complete=state.rounds.length===totalRounds();
 if(mine&&!collabDirty){collabDraft={points:String(mine.points??''),infractions:Number(mine.infractions)||0,discardTakes:Number(mine.discardTakes)||0,winner:Boolean(mine.winner)};} /* senza discardTakes la correzione del punteggio falliva («undefined/4», 10/10) */
 if(complete)return `<div class="final-dashboard"><section class="panel final-panel"><div class="round-head"><h2>${t('finalRanking')}</h2></div>${finalView()}</section></div>${historyView()}`;
 const starter=Number.isInteger(current.starterIndex)?state.players[current.starterIndex]:null;
 return `<div class="collab-layout"><section class="panel collab-card"><div class="collab-who">${avatar(state.players[me],me,'small')}<div><span>${lt('Stai giocando come','Playing as','Oyuncu')}</span><strong>${esc(state.players[me])}</strong></div></div>${connectedLine()}${current.contract?collabScoreView(current,entries,starter,mine):collabContractView()} </section><aside class="panel"><div class="section-title"><h2>${t('totalRanking')}</h2><span class="pill">${t('lowest')}</span></div>${rankingView()}</aside></div>${historyView()}<p class="share-updated">${t('autoUpdate')}</p>`;
}
function collabContractView(){const done=new Set(state.rounds.map(r=>r.contract)),available=new Set(activeContracts()),nextMini=state.mode==='mini'?activeContracts()[state.rounds.length]:null,chooser=chooserIndex(),cutter=cutterIndex();return `<p class="eyebrow">${lt('Tutti possono scegliere','Everyone can choose','Herkes seçebilir')}</p><h2>${t('chooseGame')}</h2><p class="starter-banner">🎴 Sceglie: <strong>${esc(state.players[chooser]||'—')}</strong> · 🃏 Taglia: <strong>${esc(state.players[cutter]||'—')}</strong></p><div class="contracts">${contracts.filter(([n])=>available.has(n)).map(([n,title,desc])=>{const locked=done.has(n)||(state.mode==='mini'&&n!==nextMini)||(n===16&&state.rounds.length<totalRounds()-1);return `<button class="contract-card ${locked?'locked':''}" data-collab-contract="${n}" ${locked?'disabled':''}><strong>${n}. ${title}</strong><span>${n===15?'×2 automatico · ':''}${state.mode==='mini'&&n===nextMini?lt('Prossima nella sequenza','Next in sequence','Sıradaki oyun'):desc}</span></button>`}).join('')}</div>`;}
function overrideKey(){return `amerikano-owner-override-${sharedCode||''}`;}
function loadOverrides(){try{const v=JSON.parse(localStorage.getItem(overrideKey()));return new Set(Array.isArray(v)?v.map(Number):[]);}catch{return new Set();}}
function toggleOverride(i){const o=loadOverrides();o.has(i)?o.delete(i):o.add(i);localStorage.setItem(overrideKey(),JSON.stringify([...o].sort((a,b)=>a-b)));render();}
function ownerAllowedIndices(){const claimed=new Set(collabRoom?.claimed_indices||[]),o=loadOverrides();return state.players.map((_,i)=>i).filter(i=>!claimed.has(i)||o.has(i));}
function ownerEntryModal(){const allowed=ownerAllowedIndices();if(!allowed.length){toast(lt('Sono tutti collegati: ognuno inserisce da sé. Per inserire al posto di qualcuno tocca «Inserisco io» accanto al suo nome.','Everyone is connected and enters their own score. To enter for someone, tap «I enter it» next to their name.','Herkes bağlı. Biri yerine girmek için adının yanındaki «Ben girerim»e dokunun.'));return;}const entries=collabRoom?.entries||[],done=new Set(entries.map(x=>x.playerIndex)),first=allowed.find(i=>!done.has(i))??allowed[0];closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><p class="eyebrow">🛡️ ${lt('Amministratore','Admin','Yönetici')}</p><h2>${lt('Punteggio per un altro giocatore','Score for another player','Başka bir oyuncu için puan')}</h2><div class="config-fields"><label>${lt('Giocatore','Player','Oyuncu')}<select id="owner-player">${allowed.map(i=>`<option value="${i}" ${i===first?'selected':''}>${esc(state.players[i])}${done.has(i)?' ✓':''}</option>`).join('')}</select></label><label>${t('points')}<input id="owner-points" type="number" min="0" inputmode="numeric" value=""></label><label>${lt('Infrazioni','Infractions','İhlaller')}<input id="owner-inf" type="number" min="0" inputmode="numeric" value="0"></label><label>🃏 ${lt('Prese','Pickups','Alımlar')}<input id="owner-takes" type="number" min="0" max="4" inputmode="numeric" value="0"></label><label class="switch-row"><span><strong>${t('winner')}</strong></span><input type="checkbox" id="owner-winner"></label></div><div class="actions"><button class="secondary" id="modal-cancel">${lt('Indietro','Back','Geri')}</button><button class="primary" id="owner-save">${lt('Salva','Save','Kaydet')}</button></div></div></div>`);document.querySelector('#modal-cancel').onclick=closeModal;document.querySelector('#owner-save').onclick=ownerSaveEntry;}
async function ownerSaveEntry(){if(!ownerAllowedIndices().includes(Number(document.querySelector('#owner-player')?.value))){toast(lt('Questo giocatore è collegato e inserisce da sé: per farlo tu, tocca «Inserisco io» accanto al suo nome.','This player is connected and enters their own score: to do it yourself, tap «I enter it» next to their name.','Bu oyuncu bağlı.'));return;}const index=Number(document.querySelector('#owner-player')?.value),winner=Boolean(document.querySelector('#owner-winner')?.checked),points=winner?0:Math.max(0,Number(document.querySelector('#owner-points')?.value)||0),inf=Math.max(0,Number(document.querySelector('#owner-inf')?.value)||0),takes=Math.max(0,Math.min(4,Number(document.querySelector('#owner-takes')?.value)||0));try{const ok=await ShareService.submitScoreAsOwner(shareAccess,index,points,inf,takes,winner);if(ok===false){toast(lt('Punteggio NON salvato: la mano non è aperta o non sei l’amministratore.','Score NOT saved: the round is not open or you are not the admin.','Puan KAYDEDİLMEDİ: el açık değil veya yönetici değilsiniz.'));return;}closeModal();await refreshSharedGame();toast(`${lt('Punteggio salvato per','Score saved for','Puan kaydedildi:')} ${state.players[index]||''}`);}catch{toast(lt('Invio non riuscito','Submission failed','Gönderim başarısız'));}}
async function ownerCloseRound(){try{const result=await ShareService.approveAsOwner(shareAccess);await refreshSharedGame();if(result?.finalized){toast(lt('Mano chiusa dall’amministratore','Round closed by the admin','El yönetici tarafından kapatıldı'));return;}toast(result?.reason==='scores_missing'?lt('Mancano punteggi o il vincitore','Scores or the winner are missing','Puanlar veya kazanan eksik'):lt('Mano NON chiusa','Round NOT closed','El KAPATILMADI'));}catch{toast(lt('Operazione non riuscita','Operation failed','İşlem başarısız'));}}
function collabScoreView(current,entries,starter,mine){const c=contracts[current.contract-1],submitted=Boolean(mine),owner=shareAccess?.code===sharedCode,chooser=Number.isInteger(current.starterIndex)?current.starterIndex:chooserIndex(),cutter=(chooser-2+state.players.length)%state.players.length;return `<p class="eyebrow">${t('round')} ${current.roundNo} ${t('of')} ${totalRounds()}</p><h2>${c[0]}. ${c[1]}</h2>${current.contract===15?'<span class="pill double-pill">×2 Coppie automatico</span>':''}<p class="starter-banner">🎴 Sceglie: <strong>${esc(state.players[chooser]||'—')}</strong> · 🃏 Taglia: <strong>${esc(state.players[cutter]||'—')}</strong></p><div class="my-score"><label>${t('points')}<input id="collab-points" type="number" min="0" inputmode="numeric" value="${collabDraft.winner?'':esc(collabDraft.points)}" ${collabDraft.winner?'disabled':''}></label><button class="winner-btn ${collabDraft.winner?'selected':''}" id="collab-winner">${collabDraft.winner?'✓ ':''}${winnerWord(state.players[collabSession?.playerIndex])}</button><div class="collab-infraction"><span>${lt('Infrazioni','Infractions','İhlaller')}</span><button data-collab-inf="-1" aria-label="${lt('Togli uno:','Remove one:','Bir azalt:')} ${lt('penalità','penalties','cezalar')}">−</button><strong>${collabDraft.infractions}</strong><button data-collab-inf="1" aria-label="${lt('Aggiungi uno:','Add one:','Bir ekle:')} ${lt('penalità','penalties','cezalar')}">+</button></div><div class="collab-infraction"><span>🃏 Prese</span><button data-collab-take="-1" aria-label="${lt('Togli uno:','Remove one:','Bir azalt:')} ${lt('prese dagli scarti','discard takes','ıskarta alımları')}">−</button><strong>${collabDraft.discardTakes}/4</strong><button data-collab-take="1" aria-label="${lt('Aggiungi uno:','Add one:','Bir ekle:')} ${lt('prese dagli scarti','discard takes','ıskarta alımları')}">+</button></div><button class="primary" id="collab-submit">${submitted?lt('Aggiorna il mio punteggio','Update my score','Puanımı güncelle'):lt('Invia il mio punteggio','Submit my score','Puanımı gönder')}</button></div>${collabStatusView(entries)}${owner?`<label class="switch-row"><span><strong>🃏 ${lt('Chiusura con Jolly','Joker close','Joker ile bitiş')}</strong><small style="display:block;color:var(--muted)">${lt('Raddoppia i punti della mano','Doubles the round points','El puanlarını ikiye katlar')}</small></span><input type="checkbox" id="collab-joker-close" ${current.jokerClose?'checked':''}></label>`:''}<button class="primary approve-round" id="collab-approve" ${!submitted?'disabled':''}>${mine?.approved?'✓ '+lt('Confermato','Approved','Onaylandı'):lt('Conferma tutti i punteggi','Approve all scores','Tüm puanları onayla')}</button>${owner?`<div class="menu-actions owner-tools"><p class="eyebrow menu-section">🛡️ ${lt('Amministratore','Admin','Yönetici')}</p><button class="secondary" id="owner-enter">✍️ ${lt('Inserisci per chi non ha l\'app','Enter for players without the app','Uygulaması olmayanlar için gir')}</button><button class="secondary" id="owner-close">✅ ${lt('Chiudi la mano senza aspettare le conferme','Close the round without waiting for approvals','Onayları beklemeden eli kapat')}</button></div><button class="ghost owner-reset" id="collab-reset">${lt('Annulla questa mano','Cancel this round','Bu eli iptal et')}</button>`:''}`;}
