function evRoundWinner(round){return Number.isInteger(round.winner)?round.winner:(round.results||[]).findIndex(x=>x?.winner);}
function evRoundChooser(g,round,ri){return Number.isInteger(round.chooser)?round.chooser:((Number.isInteger(g.firstChooser)?g.firstChooser:0)+ri)%(g.players?.length||1);}
function evRoundCutter(g,round,ri){const c=evRoundChooser(g,round,ri);return Number.isInteger(round.cutter)?round.cutter:(c-2+g.players.length)%g.players.length;}
function evContract(round){return `${round.contract}. ${esc(contracts[(round.contract||1)-1]?.[1]||'')}`;}
function evGames(){return allCompletedGames().slice().reverse();}
function evRoundItems(name,test){const out=[];evGames().forEach(g=>{const i=g.players.indexOf(name);if(i<0)return;(g.rounds||[]).forEach((round,ri)=>{const r=test(g,round,ri,i);if(r)out.push({when:fmtDateTime(g.startedAt),round:ri+1,contract:evContract(round),detail:r.detail||'',count:r.count??1});});});return out;}
function evGameItems(name,test){const out=[];evGames().forEach(g=>{const i=g.players.indexOf(name);if(i<0)return;const r=test(g,i);if(r)out.push({when:fmtDateTime(g.startedAt),round:null,contract:'',detail:r.detail||'',count:r.count??1,best:Boolean(r.best)});});return out;}
function evRanking(g){return g.ranking?.length?g.ranking:gameRanking(g);}
function evPositions(g){const cumulative=g.players.map(()=>0),positions=g.players.map(()=>[]);(g.rounds||[]).forEach(round=>{g.players.forEach((_,i)=>cumulative[i]+=Number(round.results?.[i]?.total)||0);const order=g.players.map((n,i)=>({i,total:cumulative[i]})).sort((a,b)=>a.total-b.total||a.i-b.i);order.forEach((x,pos)=>positions[x.i].push(pos));});const final=g.players.map((n,i)=>({i,total:cumulative[i]})).sort((a,b)=>a.total-b.total||a.i-b.i);return {cumulative,positions,final};}
