 '🚀':{field:'bestComeback',kind:'max',meaning:()=>lt('La rimonta più grande.','The biggest comeback.','En büyük geri dönüş.'),how:()=>lt('In una partita: la posizione peggiore toccata prima dell’ultima mano, meno la posizione finale.','In a game: worst position reached before the last round, minus the final position.','Bir oyunda: son elden önceki en kötü sıra eksi son sıra.'),items:n=>{const items=evGameItems(n,(g,i)=>{const {positions,final}=evPositions(g),p=positions[i],fin=final.findIndex(x=>x.i===i),worst=p.length>1?Math.max(...p.slice(0,-1)):fin,c=Math.max(0,worst-fin);return {count:c,detail:`${lt('da','from','')} ${worst+1}° ${lt('a','to','→')} ${fin+1}°`};});const top=Math.max(0,...items.map(x=>x.count));return items.map(x=>({...x,best:x.count===top&&top>0}));}},
