function awardDetailModal(icon,title,names){const info=AWARD_INFO[icon];if(!info)return;const rows=names.map(n=>{const items=info.items(n),shown=items.slice(0,40);return `<h3 class="award-person">${esc(n)}</h3>${items.length?`<div class="award-items">${shown.map(x=>`<div class="award-item${x.best?' best':''}"><span class="award-when">${x.when}${x.round?` · ${lt('mano','round','el')} ${x.round}`:''}</span>${x.contract?`<span class="award-contract">${x.contract}</span>`:''}<span class="award-detail">${x.detail}</span></div>`).join('')}${items.length>shown.length?`<p class="subtle">${lt('e altre','and','ve')} ${items.length-shown.length}</p>`:''}</div>`:`<p class="subtle">${lt('Nessuna mano o partita da mostrare.','Nothing to show.','Gösterilecek bir şey yok.')}</p>`}`;}).join('');closeModal();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><p class="eyebrow">Hall of Fame</p><h2>${icon} ${esc(title)}</h2><p class="award-meaning"><strong>${lt('Cosa significa','What it means','Anlamı')}:</strong> ${info.meaning()}</p><p class="award-how"><strong>${lt('Come si calcola','How it is calculated','Nasıl hesaplanır')}:</strong> ${info.how()}</p>${rows}<button class="ghost" id="modal-cancel">← ${lt('Statistiche','Statistics','İstatistikler')}</button></div></div>`);const back=statsReturn;document.querySelector('#modal-cancel').onclick=()=>{statsReturn=back;statisticsModal();};}
function playersByStanding(a){return [...a].sort((x,y)=>(y.weightedWins||0)-(x.weightedWins||0)||y.wins-x.wins||y.seconds-x.seconds||y.thirds-x.thirds||x.points-y.points||String(x.name).localeCompare(String(y.name),'it'));}
function statisticLeaders(a,field,{min=false,eligible=()=>true}={}){const pool=a.filter(eligible);if(!pool.length)return[];const value=min?Math.min(...pool.map(x=>x[field])):Math.max(...pool.map(x=>x[field]));return pool.filter(x=>x[field]===value);}
function awardLine(icon,title,leaders,field,suffix='',keepZero=false){if(!leaders.length)return'';if(!keepZero&&!(Number(leaders[0][field])>0))return'';if(title&&typeof title==='object')title=leaders.every(x=>isFemale(x.name))?title.f:title.m;return `<button class="award-tile" data-award="${esc(icon)}" data-award-title="${esc(title)}" data-award-names="${esc(JSON.stringify(leaders.map(x=>x.name)))}"><span class="award-icon">${icon}</span><strong class="award-title">${title}</strong><span class="award-who">${leaders.map(x=>esc(x.name)).join(' · ')}</span><span class="award-val">${leaders[0][field]}${suffix}</span><span class="award-more">${lt('Dettagli','Details','Ayrıntılar')} ›</span></button>`;}
