function statsPosition(){const m=document.querySelector('#modal .modal');if(!m||!document.querySelector('#modal [data-stat-tab]'))return null;return {scroll:Number(m.scrollTop)||0,tab:document.querySelector('#modal [data-stat-tab].active')?.dataset?.statTab||null};}
function restoreStatsPosition(pos){if(!pos)return;if(pos.tab){document.querySelectorAll('[data-stat-tab]').forEach(t=>t.classList.toggle('active',t.dataset.statTab===pos.tab));document.querySelectorAll('[data-stat-pane]').forEach(p=>{p.hidden=p.dataset.statPane!==pos.tab;});}const m=document.querySelector('#modal .modal');if(m)m.scrollTop=pos.scroll;}
