function applyLocalBackup(payload){
 if(!payload||![2,3].includes(payload.schemaVersion)||!payload.storage||typeof payload.storage!=='object'||Array.isArray(payload.storage))throw new Error('INVALID_BACKUP');
 if(payload.schemaVersion===3&&payload.application!=='amerikano')throw new Error('INVALID_BACKUP');
 const entries=Object.entries(payload.storage);
 if(!entries.length)throw new Error('INVALID_BACKUP');
 const writes=entries.map(([key,value])=>{
  if(!key.startsWith('amerikano-')||value===undefined||value===null)throw new Error('INVALID_BACKUP');
  const raw=typeof value==='string'?value:JSON.stringify(value);
  if(payload.schemaVersion===2&&raw.includes('"***"'))throw new Error('REDACTED_BACKUP');
  if(payload.schemaVersion===3&&typeof value!=='string')throw new Error('INVALID_BACKUP');
  if(payload.schemaVersion===3){
   const arrayKeys=[HISTORY_KEY,OWNED_GAMES_KEY,AUTO_SYNC_QUEUE_KEY,LAST_PLAYERS_KEY,LAST_PHOTOS_KEY];
   const objectKeys=[KEY,SHARE_KEY,HISTORY_MIGRATION_KEY,'amerikano-supabase-v1'];
   if(arrayKeys.includes(key)||objectKeys.includes(key)||key.startsWith('amerikano-player-')){
    let parsed;try{parsed=JSON.parse(raw);}catch{throw new Error('INVALID_BACKUP');}
    if(arrayKeys.includes(key)&&!Array.isArray(parsed))throw new Error('INVALID_BACKUP');
    if((objectKeys.includes(key)||key.startsWith('amerikano-player-'))&&(!parsed||typeof parsed!=='object'||Array.isArray(parsed)))throw new Error('INVALID_BACKUP');
    if(key===KEY&&(!Array.isArray(parsed.players)||!Array.isArray(parsed.rounds)))throw new Error('INVALID_BACKUP');
    if(key===HISTORY_KEY&&parsed.some(game=>!game||!Array.isArray(game.players)||!Array.isArray(game.rounds)))throw new Error('INVALID_BACKUP');
    if(key===AUTO_SYNC_QUEUE_KEY&&parsed.some(item=>!item?.state||!Array.isArray(item.state.players)||!Array.isArray(item.state.rounds)))throw new Error('INVALID_BACKUP');
   }
  }
  return [key,raw];
 });
 if(payload.schemaVersion===3){
  const imported=new Set(writes.map(([key])=>key));
  for(let i=0;i<localStorage.length;i++){
   const key=localStorage.key(i);
   if(key?.startsWith('amerikano-')&&!imported.has(key))writes.push([key,null]);
  }
 }
 const wasRestoring=backupRestoreInProgress;
 backupRestoreInProgress=true;
 if(typeof clearTimeout==='function')clearTimeout(shareSyncTimer);
 try{writeLocalStorageAtomically(writes);}
 catch(error){backupRestoreInProgress=wasRestoring;throw error;}
}
function writeLocalStorageAtomically(writes){
 const before=writes.map(([key])=>[key,localStorage.getItem(key)]);
 try{
  for(const [key,raw] of writes)if(raw===null)localStorage.removeItem(key);
  for(const [key,raw] of writes)if(raw!==null)localStorage.setItem(key,raw);
 }
 catch(error){
  // Free the imported values first: restoring a larger original value can
  // otherwise hit the same quota while newly imported keys still occupy space.
  for(const [key] of before)localStorage.removeItem(key);
  for(const [key,raw] of before)if(raw!==null)localStorage.setItem(key,raw);
  throw error;
 }
}
