// All'apertura: le partite non concluse create da questo telefono che non sono quella aperta sono state lasciate. Le concluse non si toccano.
async function cleanupAbandonedGames(){if(sharedCode||spectator||!window.ShareService?.configured?.()||!ShareService.read||!ShareService.deleteGame)return [];const tolte=[];for(const access of loadOwnedGames()){if(!access?.code||!access.ownerToken||access.code===shareAccess?.code)continue;try{const remote=await ShareService.read(access.code);const g=remote?.state;if(!g){forgetOwnedGame(access.code);continue;}const finita=(g.rounds||[]).length>=((g.contracts||[]).length||16);if(finita)continue;const ferma=Date.now()-new Date(remote.updated_at||0).getTime();if(g.entryMode==='multi'&&!(ferma>ABANDONED_MULTI_MS))continue;if(await deleteAbandonedGame(access))tolte.push(access.code);}catch{}}return tolte;}
// Una partita aperta e mai giocata non è una partita: all'apertura non la si ripropone.
function discardUnplayedAtStart(){if(sharedCode||!state.players?.length||(state.rounds||[]).length||state.entryMode==='multi')return false;const access=shareAccess?.code&&shareAccess?.ownerToken?{...shareAccess}:null;localStorage.removeItem(KEY);localStorage.removeItem(SHARE_KEY);shareAccess=null;state={players:[],rounds:[],mode:'full',contracts:[],createdAt:null};resetDraft();if(access)deleteAbandonedGame(access);return true;}
