function mdInline(s){return esc(s).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1');}
function mdToHtml(md){const out=[];let list=false;for(const raw of String(md||'').split('\n')){const line=raw.trimEnd();const h=line.match(/^(#{1,4})\s+(.*)$/),li=line.match(/^\s*[-*]\s+(.*)$/);if(!li&&list){out.push('</ul>');list=false;}if(h){const n=Math.min(4,h[1].length+1);out.push(`<h${n}>${mdInline(h[2])}</h${n}>`);}else if(li){if(!list){out.push('<ul>');list=true;}out.push(`<li>${mdInline(li[1])}</li>`);}else if(line.trim()&&!/^\|?\s*-{3,}/.test(line)){out.push(`<p>${mdInline(line)}</p>`);}}if(list)out.push('</ul>');return out.join('');}
