async function shareCurrentGame(){if(!window.ShareService?.configured()){supabaseSettings();toast(lt('Configura prima Supabase','Configure Supabase first','Önce Supabase ayarlarını yapın'));return;}try{const button=document.querySelector('#share-game');if(button){button.disabled=true;button.textContent='Preparazione link…';}if(!shareAccess&&ShareService.newAccess){shareAccess=ShareService.newAccess();localStorage.setItem(SHARE_KEY,JSON.stringify(shareAccess));rememberOwnedGame(shareAccess);}if(!shareAccess){shareAccess=await ShareService.create(state);localStorage.setItem(SHARE_KEY,JSON.stringify(shareAccess));rememberOwnedGame(shareAccess);}else{const ok=await ShareService.upsert(shareAccess,state);if(ok===false){setCloudStatus('error');throw new Error('SUPABASE_SYNC_REJECTED');}}if(ShareService.read&&!await verifyCloudCopy(shareAccess))throw new Error('SUPABASE_VERIFY_FAILED');closeModal();ShareService.shareText(shareMessage(shareAccess.code));toast(lt('Messaggio pronto','Message ready','Mesaj hazır'));}catch{const button=document.querySelector('#share-game');if(button){button.disabled=false;}toast(lt('Il cloud non ha accettato la partita: link non inviato. Riprova.','The cloud did not accept the game: link not sent. Try again.','Bulut oyunu kabul etmedi: bağlantı gönderilmedi. Tekrar deneyin.'));}}
