function queueShareSync(delay=350){if(backupRestoreInProgress||spectator||!window.ShareService?.configured()||(!state.players?.length&&!loadAutoSyncQueue().length))return;clearTimeout(shareSyncTimer);shareSyncTimer=setTimeout(async()=>{if(backupRestoreInProgress)return;try{const access=shareAccess||await ensureAutomaticShareAccess();if(backupRestoreInProgress)return;const queue=latestSnapshotsOnly(loadAutoSyncQueue(),access);saveAutoSyncQueue(queue);for(const item of queue){if(backupRestoreInProgress)return;if(!item.access&&!access)continue;const ok=await ShareService.upsert(item.access||access,item.state);if(backupRestoreInProgress)return;if(ok===false){rejectSyncItem(item);continue;}saveAutoSyncQueue(loadAutoSyncQueue().filter(x=>x.id!==item.id));}if(!backupRestoreInProgress&&state.players?.length&&access&&state.entryMode==='multi'&&await mirrorMultiFromCloud(access))return;
if(!backupRestoreInProgress&&state.players?.length&&access&&(state.rounds?.length||state.entryMode==='multi')){setCloudStatus('pending');const ok=await ShareService.upsert(access,state);if(ok===false){if(await adoptCloudIfAhead(access))return;if(await bumpIfSameRevision(access))return;const reason=await rejectionReason(access);setCloudStatus('error',reason);throw new Error('SUPABASE_SYNC_REJECTED');}if(!await verifyCloudCopy(access))scheduleVerifyRetry();}shareSyncFailures=0;}catch{setCloudStatus(navigator.onLine===false?'offline':(cloudStatus.kind==='error'?'error':'pending'),cloudStatus.kind==='error'?cloudStatus.reason:'');shareSyncFailures++;queueShareSync(Math.min(30000,2000*shareSyncFailures));}},delay);}
